Verify-File $PSCommandPath $m.script_sha256
$repo=$m.repo.Replace('/','\');$seed=$m.seed.Replace('/','\');$sha=$m.source_commit;$bundle=Join-Path 'D:\projects' $m.bundle
Verify-File $bundle $m.bundle_sha256
if(-not (Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'}
 & git -C $seed worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$build=Join-Path $repo 'build\moe-producer-gate';$null=New-Item -ItemType Directory -Path $build -Force
$recordDir=Join-Path $repo ('build\moe-producer-gate-'+$Action+'-r1');$specPath=$recordDir+'.json'
if((Test-Path $recordDir) -or (Test-Path $specPath)){throw 'Evidence exists'}
$files=@(Get-ChildItem (Join-Path $repo 'native') -Recurse -File|Where-Object {$_.Extension -in @('.c','.cpp','.h','.hpp')}|ForEach-Object {$_.FullName})
$files+=@(Get-ChildItem (Join-Path $repo 'tests\native') -File|Where-Object {$_.Extension -in @('.h','.hpp')}|ForEach-Object {$_.FullName})
$files+=@('moe_producer_gate_selftest.cpp'|ForEach-Object {Join-Path (Join-Path $repo 'tests\native') $_})
$files+=@('baiying_build_triton_moe_q8192.ps1','baiying_guarded_inference.ps1'|ForEach-Object {Join-Path (Join-Path $repo 'scripts') $_})
$inputs=@();foreach($file in ($files|Sort-Object -Unique)){$inputs+=@{file=$file.Substring($repo.Length+1);sha256=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant()}}
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=$m.script_sha256;source_manifest_sha256=(Get-FileHash $manifest -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$inputs;model='none; generated BF16 operands and original matrix/correction controls';model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false;purpose='Compare producer-local gate/up selection, ordered K16 correction, native FP32 surfaces, BF16 activation, debug endpoints and counts against the actual retained matrix and global expert-ordered correction. Original overflow32 descriptors, scattered routes, empty/full/sparse queues, low-exponent dependency and lossless preparation fallbacks are covered. Prepared inputs and generated norm controls are common before timing. The q8192 generated operator is diagnostic only; real GB10-attached model acceptance remains separate.';context_capacity=264736}

$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
$building=$Action -eq 'build';$kernel=Join-Path $build 'producer-gate.exe'
$metaPath=Join-Path $build 'build-provenance.json'
if($building){
 $selected=$kernel;if(Test-Path $selected){throw 'Binary exists'}
 $link=Join-Path $build 'hipblaslt.lib';Copy-Item 'C:\Program Files\AMD\ROCm\7.1\lib\libhipblaslt.dll.a' $link
 $spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe'
 $spec.arguments=@('-std=c++17','-O3','-DQRT_SM121_DPP_REDUCTION=1','-DQRT_SM121_COMPACT_NORMALIZE=1','-DQRT_SM121_DOT_STAGING_GROUPS=1','--offload-arch=gfx1151','-L',$build,(Join-Path $repo 'tests\native\moe_producer_gate_selftest.cpp'),'-o',$selected,'-lhipblaslt');$timeout=180
}else{
 $meta=[IO.File]::ReadAllText($metaPath)|ConvertFrom-Json
 if($meta.repo_commit -ne $sha){throw 'Build commit mismatch'}
 Verify-File $kernel $meta.artifact.sha256
 foreach($file in $meta.source_inputs){Verify-File (Join-Path $repo $file.file) $file.sha256}
 $spec.build_provenance_sha256=(Get-FileHash $metaPath -Algorithm SHA256).Hash.ToLowerInvariant()
 $spec.executable=$kernel;$spec.arguments=@();if($Action -eq 'test-q8192'){$spec.arguments=@('--q8192')};$timeout=240
}

[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $recordDir -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $recordDir 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native action or host check failed'}
if($building){
 $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;dirty_tree=$false;source_inputs=$inputs;command_file=$PSCommandPath;command_file_sha256=$m.script_sha256;compiler=$spec.executable;arguments=$spec.arguments;run_record_sha256=(Get-FileHash (Join-Path $recordDir 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();artifact=@{file=$selected;bytes=(Get-Item $selected).Length;sha256=(Get-FileHash $selected -Algorithm SHA256).Hash.ToLowerInvariant()}}

 [IO.File]::WriteAllText($metaPath,($meta|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false))
}else{
 $reports=@([IO.File]::ReadAllLines((Join-Path $recordDir 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 $wanted=if($Action -eq 'test-q8192'){1}else{5}
 if($reports.Count -ne $wanted){throw 'Incomplete producer safety reports'}
 foreach($r in $reports){
  if($r.kind -ne 'moe_producer_gate_safety' -or $r.raw_fp32_mismatches -ne 0 -or $r.bf16_mismatches -ne 0 -or -not $r.debug_parity -or -not $r.candidate_count_parity -or -not $r.redzones_pass -or -not $r.immutable_inputs -or -not $r.all_prepared_words_checked){throw 'Producer comparison failed'}
 }
 if($Action -eq 'test-q8192' -and $reports[0].tokens -ne 8192){throw 'Wrong full shape'}
}

